 if p=='13846' and r['Language_ID']=='Noiri':why='Noiri phuṇ could instead be related to the local phul flower series. The Dardic phuṇḍ comparison alone does not distinguish sphuṇṭati from a phulla-family lateral/nasal variation in Bhil.'
 if why:held.append(dict(record=r,families=[],reason=why,passNumber=68));continue
 i=ix[p];q=rules[i];acc.append(dict(record=r,parent=p,family=i,kind='reflex',citation=q['citation'],evidence=q['evidence']+' Exact survey form '+r['Form']+' is preserved.'))
